import{_ as e,o as a,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Check Compliance Content","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-33-check-compliance-content/spec.md","filePath":"feature/content-task-workflow/3-6-33-check-compliance-content/spec.md"}'),i={name:"feature/content-task-workflow/3-6-33-check-compliance-content/spec.md"};function c(h,t,r,l,d,s){return a(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="uc-—-check-compliance-content" tabindex="-1">UC — Check Compliance Content <a class="header-anchor" href="#uc-—-check-compliance-content" aria-label="Permalink to &quot;UC — Check Compliance Content&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.33</td></tr><tr><td>Feature</td><td>Check Compliance Content</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>CREATOR, CLIENT</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Check đạo văn, bạo lực, hình ảnh dung tục qua API bên thứ 3 — trả bảng phân tích chi tiết để Creator tự sửa trước khi vi phạm chính sách nền tảng hoặc mất khả năng lên trending.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Creator hoặc Client, tôi muốn kiểm tra content có vi phạm chính sách không, để chủ động sửa trước khi đăng lên social media.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Chạy check trên nội dung Task (loại Post): text (đạo văn), hình ảnh (bạo lực, dung tục).</li><li>Dùng API bên thứ 3 (moderation service) — trả về kết quả chuẩn nhất có thể.</li><li>Hiển thị bảng phân tích: từ ngữ/đoạn vi phạm cụ thể, mức độ nghiêm trọng, gợi ý sửa.</li><li>Nếu phát hiện vi phạm nghiêm trọng → có thể tự động đưa vào Content Moderation Queue để Admin review (xem <a href="./../../../BA/09-admin-management.html">09-admin-management.md</a> FR 3.10.4).</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Nút &#39;Check Compliance&#39; trong Task Detail (loại Post), hiển thị kết quả dạng bảng highlight đoạn vi phạm.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/workspaces/{id}/tasks/{taskId}/compliance-check</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;violations&quot;: [{ &quot;type&quot;, &quot;excerpt&quot;, &quot;severity&quot;, &quot;suggestion&quot; }] } }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>API bên thứ 3 timeout/lỗi → 502 <code>COMPLIANCE_SERVICE_UNAVAILABLE</code>, cho phép retry.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Content không có vi phạm nào → trả <code>violations: []</code>, hiển thị badge &#39;Đã qua kiểm duyệt&#39;.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Check hoạt động, hiển thị đúng bảng phân tích vi phạm.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/05-content-task-workflow.html">05-content-task-workflow.md</a></p>`,22)])])}const m=e(i,[["render",c]]);export{p as __pageData,m as default};
